package com.aoo.bcg.wordcard;
import com.aoo.bcg.gamespi.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class PxphzNineStageAcceptanceTest{
 @Test void createJoinReadyStartOperateRotateReconnectReplay(){PxphzGameProvider p=new PxphzGameProvider();PxphzSession s=(PxphzSession)p.roomFactory().create(new RoomCreationContext(59601,10,Map.of("playerCount",2,"drawRemoval",10,"charge",1,"guChou",true))).requireAuthoritativeSession();StatePayload base=StatePayload.copyOf(s.authoritativeState());s.execute(cmd(1,1,20,"join",Map.of()));s.execute(cmd(2,1,20,"ready",Map.of()));s.execute(cmd(3,0,10,"piao",Map.of(),Map.of("piao",2)));Map<String,Object>v=s.execute(cmd(4,0,10,"start",Map.of())).body().asMap();assertEquals("PLAYING",v.get("phase"));Map<?,?>seats=(Map<?,?>)v.get("seats");assertEquals(21,((Map<?,?>)seats.get(0)).get("cardCount"));assertEquals(20,((Map<?,?>)seats.get(1)).get("cardCount"));List<?>cards=(List<?>)((Map<?,?>)seats.get(0)).get("cards");s.execute(cmd(5,0,10,"operation",Map.of("operation","DISCARD","cards",List.of(cards.getFirst()))));assertEquals(0,s.execute(cmd(6,1,20,"operation",Map.of("operation","PASS"))).body().asMap().get("currentSeat"));Map<?,?>hidden=(Map<?,?>)((Map<?,?>)s.viewFor(20).get("seats")).get(0);assertTrue(((List<?>)hidden.get("cards")).stream().allMatch(x->x.equals(0)));StatePayload replay=p.eventReplayProvider().orElseThrow().replay(base,s.events());assertEquals(s.authoritativeState(),replay.asMap());assertEquals(s.viewFor(20),p.restoreAuthoritativeSession(replay).orElseThrow().viewFor(20));assertTrue(s.invariantViolations().isEmpty());}
 @Test void serviceLoaderIsAtomicAndBoundaryIsUnique(){List<GameProvider>x=ServiceLoader.load(GameProvider.class).stream().map(ServiceLoader.Provider::get).toList();assertEquals(0,x.stream().filter(p->p.getClass()==PxphzGameProvider.class).count());PxphzGameProvider p=new PxphzGameProvider();assertTrue(p.ruleComponents().getFirst().execute(new GameCommandRequest("wordcard.pxphz.dispatch","x",1,1,0,"1.0.0","1",0,Map.of())).accepted());assertFalse(p.ruleComponents().getFirst().execute(new GameCommandRequest("CPXPHZOpCard","x",1,1,0,"1.0.0","1",0,Map.of())).accepted());}
 private static GameCommandRequest cmd(long n,int seat,long player,String action,Map<String,Object>payload){return cmd(n,seat,player,action,payload,Map.of());}private static GameCommandRequest cmd(long n,int seat,long player,String action,Map<String,Object>payload,Map<String,Object>extra){Map<String,Object>b=new LinkedHashMap<>(extra);b.put("action",action);b.put("payload",payload);return new GameCommandRequest("wordcard.pxphz.dispatch","pxphz-"+n,n,59601,0,"1.0.0",String.valueOf(player),seat,b);}
}
